.spec-card-wrapper {
  border: 1px solid #e5e5e5;
  border-radius: 8px;
  background: #ffffff;
  margin: 24px 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
  box-shadow: 0 2px 8px rgba(0,0,0,0.04);
  overflow: hidden;
  box-sizing: border-box;
}
.spec-card-wrapper * { box-sizing: border-box; }
.spec-main-body { display: table; width: 100%; table-layout: fixed; }

/* 电脑端左右布局 */
.spec-panel-left { display: table-cell; width: 28%; background: #fafafa; border-right: 1px solid #eee; vertical-align: top; padding: 24px 16px; text-align: center; }
.spec-panel-right { display: table-cell; width: 72%; padding: 20px 24px; vertical-align: top; }

.spec-img-box { width: 100%; margin-bottom: 16px; text-align: center; }
.spec-img-box img { max-width: 100%; max-height: 160px; object-fit: contain; border-radius: 4px; display: inline-block; }
.spec-main-title { margin: 0 0 12px 0; font-size: 16px; color: #111; font-weight: 600; line-height: 1.4; }

.spec-tags-container { display: flex; flex-wrap: wrap; gap: 6px; justify-content: center; }
.spec-tag { background: #f3f3f3; color: #555; padding: 2px 6px; font-size: 11px; border-radius: 4px; border: 1px solid #e8e8e8; white-space: nowrap; }

.spec-group-title { font-weight: bold; font-size: 13px; color: #222; border-bottom: 2px solid #333; padding: 14px 0 6px 0; margin-top: 8px; }

/* 表格行样式：电脑端单行两列 */
.spec-row { display: flex; justify-content: space-between; align-items: flex-start; padding: 8px 0; border-bottom: 1px dashed #efefef; gap: 12px; }
.spec-key { color: #666; font-size: 12px; min-width: 80px; flex-shrink: 0; text-align: left; }
.spec-val { color: #222; font-size: 12px; text-align: right; word-break: break-word; overflow-wrap: break-word; }

/* 📱 核心：移动端/手机端极端适配方案 */
@media (max-width: 767px) {
  .spec-main-body { display: block; }
  .spec-panel-left { display: block; width: 100%; border-right: none; border-bottom: 1px solid #eee; padding: 20px 16px; }
  .spec-panel-right { display: block; width: 100%; padding: 16px 16px; }

  .spec-img-box img { max-height: 140px; }
  .spec-main-title { font-size: 15px; margin-bottom: 8px; }

  /* 手机端由于屏幕窄，将左右并排改为上下并排，彻底解决数据被截断显示不全的问题 */
  .spec-row { flex-direction: column; justify-content: flex-start; align-items: stretch; gap: 4px; padding: 8px 0; }
  .spec-key { min-width: 100%; color: #888; font-size: 11px; text-align: left; }
  .spec-val { text-align: left; font-size: 12px; color: #111; padding-left: 2px; }
}




